questionvariables.text:
/* Design backwards: choose cos(theta) = k = s*p/q first (a fraction, no surds), then show the equation
   A*cos(theta) + B = 0 with A = c*q and B = -c*s*p.
   8 fractions x 2 signs x 2 coefficients (c = 1 or 2) = 32 distinct variants. */
fr : [[1,2], [1,4], [3,4], [1,3], [2,3], [2,5], [3,5], [4,5]];
pq : rand(fr);
p : pq[1];
q : pq[2];
s : rand([-1, 1]);
c : rand([1, 2]);
k : s*p/q;                    /* cos(theta) = k */
A : c*q;
B : -c*s*p;
eqn : A*cos(theta) + B = 0;

/* Reference angle and solutions (degrees) */
alpha : float(acos(p/q)*180/%pi);
x1 : if s = 1 then alpha else 180 - alpha;
x2 : if s = 1 then 360 - alpha else 180 + alpha;
/* the solutions of cos(theta) = -k: the common sign / "180 - theta" mistake */
w1 : if s = 1 then 180 - alpha else alpha;
w2 : if s = 1 then 180 + alpha else 360 - alpha;
/* answers rounded to 1 decimal place */
ta_a : round(alpha*10)/10;
r1 : round(x1*10)/10;
r2 : round(x2*10)/10;
rw1 : round(w1*10)/10;
/* decimal displays */
alpha_disp : dispdp(alpha, 1);
x1_disp : dispdp(x1, 1);
x2_disp : dispdp(x2, 1);
acosk_disp : dispdp(float(acos(k)*180/%pi), 1);

/* Quadrants: cosine is positive in I and IV, negative in II and III */
qlist : if s = 1 then [1, 4] else [2, 3];
qset : setify(qlist);
wrongqset : if s = 1 then {2, 3} else {1, 4};
qopts : [[1, is(member(1, qlist)), "Quadrant I"], [2, is(member(2, qlist)), "Quadrant II"],
         [3, is(member(3, qlist)), "Quadrant III"], [4, is(member(4, qlist)), "Quadrant IV"]];
ta_quad1 : qlist[1];
ta_quad2 : qlist[2];

/* Possible student mistakes */
k_neg : -k;                   /* sign error when rearranging */
k_nodiv : -B;                 /* moved the constant but did not divide by A */
alpha_rad : float(acos(p/q)); /* calculator in radian mode */

feedbackvariables.text:
/* allow 0.06 for rounding to 1 decimal place */
ok : is(abs(ans1 - x1) <= 0.06 or abs(ans1 - x2) <= 0.06);
outr : is(abs(ans1 + 360 - x1) <= 0.06 or abs(ans1 + 360 - x2) <= 0.06 or abs(ans1 - 360 - x1) <= 0.06 or abs(ans1 - 360 - x2) <= 0.06);
wsign : is(abs(ans1 - w1) <= 0.06 or abs(ans1 - w2) <= 0.06);
inrad : is(abs(ans1 - x1*%pi/180) <= 0.006 or abs(ans1 - x2*%pi/180) <= 0.006);

/* allow 0.06 for rounding to 1 decimal place */
ok : is(abs(ans2 - x1) <= 0.06 or abs(ans2 - x2) <= 0.06);
dup : is(abs(ans2 - ans1) <= 0.06);
okdistinct : is(ok and not dup);
outr : is(abs(ans2 + 360 - x1) <= 0.06 or abs(ans2 + 360 - x2) <= 0.06 or abs(ans2 - 360 - x1) <= 0.06 or abs(ans2 - 360 - x2) <= 0.06);
wsign : is(abs(ans2 - w1) <= 0.06 or abs(ans2 - w2) <= 0.06);
inrad : is(abs(ans2 - x1*%pi/180) <= 0.006 or abs(ans2 - x2*%pi/180) <= 0.006);
